Miquéias 5 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Segundo o capítulo, o que será ferido com a vara?","o":["A face do juiz de Israel","A mão do rei de Judá","A cabeça do sumo sacerdote","As costas do profeta"],"c":0,"v":1,"e":"O versículo 1 diz que ferirão com a vara a face do juiz de Israel."},
 {"t":"multipla","p":"De que lugar sairá aquele que deve reinar em Israel?","o":["Jerusalém","Samaria","Belém","Siló"],"c":2,"v":2,"e":"O versículo 2 diz que de Belém, pequena entre os milhares de Judá, sairá aquele que deve reinar em Israel."},
 {"t":"multipla","p":"Quando a Assíria vier à terra, quem será levantado contra ela?","o":["Doze juízes e doze profetas","Sete pastores e oito príncipes","Três reis e mil soldados","Dez anciãos e dez sacerdotes"],"c":1,"v":5,"e":"O versículo 5 diz que levantarão contra a Assíria sete pastores e oito príncipes dentre os homens."},
 {"t":"multipla","p":"Entre muitos povos, o remanescente de Jacó será como o quê?","o":["Fogo consumidor","Orvalho do Senhor","Pedra angular","Rio caudaloso"],"c":1,"v":7,"e":"O versículo 7 compara o remanescente de Jacó ao orvalho do Senhor e aos chuviscos sobre a erva."},
 {"t":"multipla","p":"\"Naquele dia\", o que o Senhor diz que vai eliminar e destruir primeiro?","o":["Os templos e os altares","Os reis e os príncipes","Os campos e as vinhas","Os cavalos e os carros de guerra"],"c":3,"v":10,"e":"O versículo 10 diz que o Senhor eliminará os cavalos e destruirá os carros de guerra."},
 {"t":"cv","p":"Os pastores e príncipes devastarão à espada a terra do Egito.","c":false,"v":6,"e":"O versículo 6 fala da terra da Assíria e da terra de Ninrode, não do Egito."},
 {"t":"cv","p":"O Senhor diz que eliminará as feitiçarias e que não haverá mais adivinhadores.","c":true,"v":12,"e":"O versículo 12 diz que o Senhor eliminará as feitiçarias e que não haverá adivinhadores."},
 {"t":"cv","p":"No fim do capítulo, o Senhor diz que tomará vingança, com ira e furor, sobre as nações que não lhe obedecem.","c":true,"v":15,"e":"O versículo 15 diz que, com ira e furor, o Senhor tomará vingança sobre as nações que não lhe obedecem."}
]}

Miquéias 7 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"No início do capítulo, com quem o profeta se compara?","o":["Com quem colhe as frutas do verão e não acha cacho de uvas para comer","Com o pastor que perdeu suas ovelhas no deserto","Com o lavrador que semeia e não colhe trigo","Com a sentinela que vigia o muro durante a noite"],"c":0,"v":1,"e":"No versículo 1, o profeta diz que está como quem colhe as frutas do verão, sem cacho de uvas nem figos precoces."},
 {"t":"multipla","p":"Segundo o capítulo, o que o juiz faz?","o":["Defende o pobre","Aceita suborno","Foge da cidade","Consulta os profetas"],"c":1,"v":3,"e":"O versículo 3 diz que o príncipe exige condenação e o juiz aceita suborno."},
 {"t":"multipla","p":"Quem o profeta diz que são os inimigos do homem?","o":["Os povos vizinhos","Os sacerdotes do templo","Os de sua própria casa","Os reis da Assíria"],"c":2,"v":6,"e":"O versículo 6 afirma que os inimigos do homem são os de sua própria casa."},
 {"t":"multipla","p":"Diante de toda essa corrupção, o que o profeta diz que fará?","o":["Fugirá para o Egito","Olhará para o Senhor e esperará no Deus da sua salvação","Fará justiça com as próprias mãos","Ficará em silêncio no deserto"],"c":1,"v":7,"e":"No versículo 7, o profeta diz que olhará para o Senhor e esperará no Deus da sua salvação."},
 {"t":"multipla","p":"O que a inimiga diz ao profeta?","o":["\"Onde está o SENHOR, teu Deus?\"","\"Teus muros nunca serão reerguidos.\"","\"Teu povo será levado para a Babilônia.\"","\"Não há profeta em Israel.\""],"c":0,"v":10,"e":"O versículo 10 cita a inimiga dizendo: \"Onde está o SENHOR, teu Deus?\""},
 {"t":"cv","p":"O Senhor promete mostrar maravilhas como nos dias em que o povo saiu da terra do Egito.","c":true,"v":15,"e":"O versículo 15 diz: \"Mostrarei maravilhas a vocês, como nos dias em que saíram da terra do Egito\"."},
 {"t":"cv","p":"O capítulo diz que Deus retém sua ira para sempre.","c":false,"v":18,"e":"O versículo 18 diz o contrário: Deus não retém sua ira para sempre, porque se alegra em demonstrar misericórdia."},
 {"t":"cv","p":"O profeta diz que Deus lançará todos os pecados do povo no deserto.","c":false,"v":19,"e":"Segundo o versículo 19, Deus lançará todos os pecados nas profundezas do mar."}
]}

Miquéias 1 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Nos dias de quais reis de Judá veio a visão a Miquéias?","o":["Uzias, Jotão e Acaz","Jotão, Acaz e Ezequias","Acaz, Ezequias e Manassés","Ezequias, Manassés e Josias"],"c":1,"v":1,"e":"O versículo 1 diz que a visão veio nos dias de Jotão, Acaz e Ezequias, reis de Judá."},
 {"t":"multipla","p":"Quando o Senhor desce, os montes se derretem como o quê?","o":["Como a neve diante do sol","Como o sal na água","Como a cera diante do fogo","Como a areia levada pelo vento"],"c":2,"v":4,"e":"O versículo 4 compara os montes à cera que se derrete diante do fogo."},
 {"t":"multipla","p":"Segundo o texto, qual é a transgressão de Jacó?","o":["Samaria","Jerusalém","Gate","Laquis"],"c":0,"v":5,"e":"O versículo 5 pergunta qual é a transgressão de Jacó e responde: Samaria."},
 {"t":"multipla","p":"O que o Senhor diz que fará de Samaria?","o":["Uma cidade fortificada","Um montão de pedras do campo","Um lugar de refúgio para os povos","Uma morada para os reis de Judá"],"c":1,"v":6,"e":"No versículo 6 o Senhor diz que fará de Samaria um montão de pedras do campo."},
 {"t":"multipla","p":"Com que animais o profeta compara seus lamentos e seu pranto?","o":["Leões e águias","Lobos e corvos","Chacais e avestruzes","Cães e pombas"],"c":2,"v":8,"e":"O versículo 8 fala em lamentos como de chacais e pranto como de avestruzes."},
 {"t":"cv","p":"A ferida incurável se espalhou até Judá e alcançou a porta de Jerusalém.","c":true,"v":9,"e":"O versículo 9 diz que a ferida se espalhou até Judá e alcançou a porta do povo, até Jerusalém."},
 {"t":"cv","p":"Gate é chamada de princípio do pecado para a filha de Sião.","c":false,"v":13,"e":"No versículo 13 quem é chamada de princípio do pecado para a filha de Sião é a moradora de Laquis, não Gate."},
 {"t":"cv","p":"O povo deve ficar calvo porque os filhos que eram sua alegria serão levados para o cativeiro.","c":true,"v":16,"e":"O versículo 16 manda ficar calvo por causa dos filhos, porque serão levados para o cativeiro."}
]}

Miquéias 4 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Nos últimos dias, onde será estabelecido o monte da casa do Senhor?","o":["No cimo dos montes","No vale do Jordão","À beira do mar","No deserto de Judá"],"c":0,"v":1,"e":"O versículo 1 diz que o monte da casa do Senhor será estabelecido no cimo dos montes."},
 {"t":"multipla","p":"Por que as muitas nações querem subir ao monte do Senhor?","o":["Para oferecer seus tesouros","Para que ele lhes ensine os seus caminhos","Para fazer guerra contra Jacó","Para escolher um rei"],"c":1,"v":2,"e":"No versículo 2, as nações dizem que sobem para que o Senhor lhes ensine os seus caminhos."},
 {"t":"multipla","p":"Em que as nações converterão suas espadas?","o":["Em foices","Em cajados de pastor","Em relhas de arados","Em pregos de construção"],"c":2,"v":3,"e":"O versículo 3 diz que converterão suas espadas em relhas de arados."},
 {"t":"multipla","p":"Debaixo de que cada um se sentará, sem que ninguém o espante?","o":["Da sua oliveira e da sua palmeira","Da sua tenda","Do seu cedro","Da sua videira e da sua figueira"],"c":3,"v":4,"e":"O versículo 4 diz que cada um se sentará debaixo da sua videira e debaixo da sua figueira."},
 {"t":"multipla","p":"Naquele dia, quem o Senhor diz que vai congregar?","o":["Os que coxeiam","Os reis da terra","Os sacerdotes do templo","Os ricos de Jerusalém"],"c":0,"v":6,"e":"No versículo 6, o Senhor diz: congregarei os que coxeiam."},
 {"t":"cv","p":"O texto diz que a filha de Sião iria até Babilônia e que ali seria libertada.","c":true,"v":10,"e":"O versículo 10 diz que ela irá até Babilônia e que ali será libertada."},
 {"t":"cv","p":"As nações que se congregaram contra Sião conheciam os pensamentos do Senhor e entendiam o seu plano.","c":false,"v":12,"e":"O versículo 12 diz que elas não conhecem os pensamentos do Senhor nem entendem o seu plano."},
 {"t":"cv","p":"O Senhor diz que fará de ferro o chifre da filha de Sião e de bronze as suas unhas.","c":true,"v":13,"e":"O versículo 13 diz que o Senhor fará de ferro o seu chifre e de bronze as suas unhas."}
]}

Miquéias 3 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"A quem o profeta se dirige no começo do capítulo?","o":["Aos sacerdotes do templo","Aos cabeças de Jacó e príncipes da casa de Israel","Aos reis das nações vizinhas","Aos moradores de Samaria"],"c":1,"v":1,"e":"No versículo 1 o profeta chama os cabeças de Jacó e os príncipes da casa de Israel para ouvir."},
 {"t":"multipla","p":"O que acontecerá quando esses líderes clamarem ao Senhor?","o":["Ele os perdoará na mesma hora","Ele enviará um profeta para guiá-los","Ele não os ouvirá e esconderá deles a Sua face","Ele mandará chuva sobre a terra"],"c":2,"v":4,"e":"O versículo 4 diz que o Senhor não os ouvirá e esconderá deles a Sua face, porque fizeram o mal."},
 {"t":"multipla","p":"Os profetas que fazem o povo errar clamam \"Paz!\", mas preparam guerra contra quem?","o":["Contra quem nada lhes oferece para comer","Contra os sacerdotes","Contra os estrangeiros","Contra os reis de Judá"],"c":0,"v":5,"e":"O versículo 5 diz que eles preparam guerra contra aqueles que nada lhes oferecem para comer."},
 {"t":"multipla","p":"Por que os videntes e adivinhadores ficarão envergonhados?","o":["Porque o povo os expulsou da cidade","Porque perderam suas riquezas","Porque o templo foi destruído","Porque não há resposta de Deus"],"c":3,"v":7,"e":"O versículo 7 diz que todos cobrirão o bigode, pois não há resposta de Deus."},
 {"t":"multipla","p":"De que o profeta diz estar cheio para declarar a Jacó a sua transgressão?","o":["De riquezas e honra","Do poder do Espírito do SENHOR, de juízo e de força","De medo e tristeza","Da sabedoria dos anciãos"],"c":1,"v":8,"e":"No versículo 8 o profeta diz estar cheio do poder do Espírito do SENHOR, repleto de juízo e de força."},
 {"t":"cv","p":"Os líderes edificam Sião com sangue e Jerusalém com perversidade.","c":true,"v":10,"e":"O versículo 10 diz exatamente que eles edificam Sião com sangue e Jerusalém com perversidade."},
 {"t":"cv","p":"Segundo o capítulo, os profetas de Jerusalém faziam previsões sem cobrar nada.","c":false,"v":11,"e":"O versículo 11 diz que os profetas fazem previsões por dinheiro."},
 {"t":"cv","p":"Por causa desses líderes, Sião será lavrada como um campo e Jerusalém se tornará montões de ruínas.","c":true,"v":12,"e":"O versículo 12 anuncia que Sião será lavrada como um campo e Jerusalém virará montões de ruínas."}
]}

Miquéias 6 Â· exercÃ­cios.texto:
{"perguntas":[
{"t":"multipla","p":"Diante de quem o Senhor apresenta a sua queixa contra o povo?","o":["Os montes e os fundamentos da terra","Os sacerdotes do templo","Os reis de Judá","Os anjos do céu"],"c":0,"v":2,"e":"No versículo 2, os montes e os fundamentos sólidos da terra são chamados a ouvir a queixa do Senhor."},
{"t":"multipla","p":"Quem o Senhor diz ter enviado à frente do povo quando o tirou do Egito?","o":["Josué, Calebe e Arão","Moisés, Arão e Miriã","Moisés, Josué e Samuel","Abraão, Isaque e Jacó"],"c":1,"v":4,"e":"O versículo 4 diz que Deus enviou Moisés, Arão e Miriã à frente do povo."},
{"t":"multipla","p":"Segundo o capítulo, quem era Balaque?","o":["Rei de Edom","Rei de Moabe","Filho de Beor","Profeta de Israel"],"c":1,"v":5,"e":"O versículo 5 apresenta Balaque como rei de Moabe; o filho de Beor era Balaão."},
{"t":"multipla","p":"O que o Senhor exige do homem?","o":["Que ofereça holocaustos e bezerros de um ano","Que dê milhares de carneiros e ribeiros de azeite","Que pratique a justiça, ame a misericórdia e ande humildemente com Deus","Que entregue o primogênito pela sua transgressão"],"c":2,"v":8,"e":"O versículo 8 responde às perguntas dos versículos 6 e 7: praticar a justiça, amar a misericórdia e andar humildemente com Deus."},
{"t":"multipla","p":"Que prática desonesta o Senhor condena no comércio?","o":["Moedas de prata falsificadas","Contratos escritos com mentira","Vinho misturado com água","Balanças falsas e pesos enganadores"],"c":3,"v":11,"e":"O versículo 11 fala de balanças falsas e bolsas de pesos enganadores."},
{"t":"cv","p":"Segundo o capítulo, os ricos da cidade estão repletos de violência.","c":true,"v":12,"e":"O versículo 12 diz que os ricos da cidade estão repletos de violência e que os habitantes falam mentiras."},
{"t":"cv","p":"O Senhor diz que o povo pisaria a azeitona e se ungiria com o azeite.","c":false,"v":15,"e":"O versículo 15 diz que o povo pisaria a azeitona, mas não se ungiria com o azeite."},
{"t":"cv","p":"O povo seguiu os estatutos de Omri e as obras da casa de Acabe.","c":true,"v":16,"e":"O versículo 16 afirma que o povo seguiu os estatutos de Omri e todas as obras da casa de Acabe."}
]}

Miquéias 2 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Onde os que maquinam o mal imaginam a iniquidade?","o":["Nas praças da cidade","Em suas camas","No templo","Nos campos"],"c":1,"v":1,"e":"O versículo 1 diz que eles imaginam a iniquidade em suas camas e a realizam ao amanhecer."},
 {"t":"multipla","p":"O que essas pessoas cobiçam e tomam?","o":["Campos e casas","Ovelhas e bois","Ouro e prata","Vinhas e poços"],"c":0,"v":2,"e":"O versículo 2 diz que eles cobiçam campos e os tomam, e casas e se apossam delas."},
 {"t":"multipla","p":"O que o Senhor diz que está tramando contra esta família?","o":["Uma aliança de paz","Um mal do qual não conseguirão erguer a cerviz","Uma grande colheita","Uma festa de libertação"],"c":1,"v":3,"e":"No versículo 3 o Senhor diz que trama um mal do qual eles não conseguirão erguer a cerviz."},
 {"t":"multipla","p":"No lamento, entre quem os campos do povo são repartidos?","o":["Os sacerdotes","Os estrangeiros","Os rebeldes","Os pobres"],"c":2,"v":4,"e":"O lamento do versículo 4 diz: Reparte os nossos campos entre os rebeldes!"},
 {"t":"multipla","p":"O que é dito aos que profetizam?","o":["Que profetizem com mais força","Que profetizem só no templo","Que profetizem a favor do rei","Que não profetizem desse modo, porque a desgraça não cairá sobre eles"],"c":3,"v":6,"e":"O versículo 6 traz a ordem de não profetizar desse modo, alegando que a desgraça não cairá sobre eles."},
 {"t":"cv","p":"O povo é acusado de expulsar as mulheres do povo de seus lares amados.","c":true,"v":9,"e":"O versículo 9 diz: Expulsastes as mulheres do meu povo de seus lares amados."},
 {"t":"cv","p":"O profeta aceito por este povo seria aquele que falasse a verdade com retidão.","c":false,"v":11,"e":"O versículo 11 diz que seria profeta deste povo quem mentisse prometendo profetizar do vinho e da bebida forte."},
 {"t":"cv","p":"No fim do capítulo, o Rei do povo vai adiante deles, e o Senhor à sua frente.","c":true,"v":13,"e":"O versículo 13 diz que o seu Rei irá adiante deles, sim, o Senhor à sua frente."}
]}
